CREATE TABLE IF NOT EXISTS behavior_incidents (id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE, incident_date DATE NOT NULL DEFAULT CURRENT_DATE, kind TEXT NOT NULL DEFAULT 'minor' CHECK (kind IN ('minor','major','positive')), category TEXT, description TEXT NOT NULL, action_taken TEXT, recorded_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS medical_records (id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE, record_type TEXT NOT NULL DEFAULT 'note' CHECK (record_type IN ('immunization','allergy','medication','condition','note')), title TEXT NOT NULL, details TEXT NULL, recorded_on DATE NOT NULL DEFAULT CURRENT_DATE, recorded_by BIGINT NULL REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_behavior_student ON behavior_incidents (student_id, incident_date);
CREATE INDEX IF NOT EXISTS idx_medical_student ON medical_records (student_id, recorded_on);
